const { antragstyp, formData, email } = $input.item.json.body ?? {};

const requiredFieldsByType = {
  wohngeld: [
    "name",
    "geburtsdatum",
    "strasse",
    "plz",
    "ort",
    "haushaltsgroesse",
    "bruttoeinkommen",
    "sozialleistungen",
    "kaltmiete",
    "nebenkosten",
  ],
  kinderzuschlag: [
    "name",
    "strasse",
    "plz",
    "ort",
    "anzahlKinder",
    "alterKinder",
    "einkommen",
    "wohnkosten",
    "kindergeldBezug",
  ],
  elterngeld: [
    "name",
    "strasse",
    "plz",
    "ort",
    "geburtsterminKind",
    "einkommenVorGeburt",
    "arbeitgeber",
    "elternzeitMonate",
  ],
  pflegegeld: [
    "antragsart",
    "name",
    "strasse",
    "plz",
    "ort",
  ],
};

const requiredFields = requiredFieldsByType[antragstyp];
if (!requiredFields) {
  throw new Error(`Unbekannter Antragstyp: "${antragstyp}"`);
}

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email || !emailPattern.test(email)) {
  throw new Error("Fehlende oder ungültige E-Mail-Adresse.");
}

const missingFields = requiredFields.filter((field) => {
  const value = formData ? formData[field] : undefined;
  return value === undefined || value === null || value === "";
});

if (missingFields.length > 0) {
  throw new Error(`Folgende Pflichtfelder fehlen: ${missingFields.join(", ")}`);
}

return { json: { antragstyp, formData, email, quelle: "wizard" } };

function escapeHtml(value) {
  return String(value ?? "").replace(/[&<>"']/g, (c) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  }[c]));
}

function formatDate(value) {
  if (!value) return "";
  const [year, month, day] = String(value).split("-");
  if (!year || !month || !day) return escapeHtml(value);
  return `${day}.${month}.${year}`;
}

function formatCurrency(value) {
  const number = Number(value);
  if (Number.isNaN(number)) return escapeHtml(value);
  return number.toLocaleString("de-DE", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " €";
}

const { antragstyp, formData, email, quelle } = $input.item.json;
const generatedAt = new Date().toLocaleDateString("de-DE", { year: "numeric", month: "long", day: "numeric" });

const baseStyles = `
  body { font-family: 'Helvetica Neue', Arial, sans-serif; color: #1a202c; margin: 0; padding: 0; }
  .page { padding: 32px 48px 48px; }
  header { background: #1a365d; color: #ffffff; padding: 28px 48px; }
  header h1 { margin: 0; font-size: 22px; }
  header p { margin: 4px 0 0; font-size: 13px; color: #cbd5e0; }
  h2 { font-size: 15px; color: #1a365d; border-bottom: 2px solid #38a169; padding-bottom: 6px; margin-top: 28px; }
  dl { display: grid; grid-template-columns: 200px 1fr; row-gap: 8px; column-gap: 12px; margin: 12px 0; }
  dt { font-weight: 600; color: #4a5568; font-size: 13px; }
  dd { margin: 0; font-size: 13px; }
  footer { margin-top: 40px; font-size: 11px; color: #a0aec0; border-top: 1px solid #e2e8f0; padding-top: 12px; }
`;

function renderWohngeld(formData) {
  return `
    <dl>
      <dt>Name</dt><dd>${escapeHtml(formData.name)}</dd>
      <dt>Geburtsdatum</dt><dd>${formatDate(formData.geburtsdatum)}</dd>
    </dl>
    <h2>Adresse</h2>
    <dl>
      <dt>Straße</dt><dd>${escapeHtml(formData.strasse)}</dd>
      <dt>PLZ / Ort</dt><dd>${escapeHtml(formData.plz)} ${escapeHtml(formData.ort)}</dd>
    </dl>
    <h2>Haushalt</h2>
    <dl>
      <dt>Haushaltsgröße</dt><dd>${escapeHtml(formData.haushaltsgroesse)} Personen</dd>
      <dt>Bruttoeinkommen</dt><dd>${formatCurrency(formData.bruttoeinkommen)} / Monat</dd>
      <dt>Sozialleistungen</dt><dd>${formData.sozialleistungen === "ja" ? "Ja" : "Nein"}</dd>
    </dl>
    <h2>Wohnung</h2>
    <dl>
      <dt>Kaltmiete</dt><dd>${formatCurrency(formData.kaltmiete)} / Monat</dd>
      <dt>Nebenkosten</dt><dd>${formatCurrency(formData.nebenkosten)} / Monat</dd>
    </dl>
  `;
}

function renderPflegegeld(formData) {
  const antragsartLabels = {
    zuerkennung: "die Zuerkennung des Pflegegeldes",
    erhoehung: "die Erhöhung des Pflegegeldes",
  };
  return `
    <dl>
      <dt>Ich beantrage</dt><dd>${escapeHtml(antragsartLabels[formData.antragsart] ?? formData.antragsart)}</dd>
      <dt>Name</dt><dd>${escapeHtml(formData.name)}</dd>
    </dl>
    <h2>Adresse</h2>
    <dl>
      <dt>Straße</dt><dd>${escapeHtml(formData.strasse)}</dd>
      <dt>PLZ / Ort</dt><dd>${escapeHtml(formData.plz)} ${escapeHtml(formData.ort)}</dd>
    </dl>
  `;
}

function renderGeneric(formData) {
  const rows = Object.entries(formData || {})
    .map(([key, value]) => `<dt>${escapeHtml(key)}</dt><dd>${escapeHtml(value)}</dd>`)
    .join("");
  return `<h2>Angaben</h2><dl>${rows}</dl><p style="margin-top:16px;font-size:12px;color:#a0aec0;">Detaillierte Vorlage für diesen Antragstyp folgt in Kürze – aktuell werden alle übermittelten Felder aufgelistet.</p>`;
}

const titles = {
  wohngeld: "Antrag auf Wohngeld",
  kinderzuschlag: "Antrag auf Kinderzuschlag",
  elterngeld: "Antrag auf Elterngeld",
  pflegegeld: "Antrag auf Pflegegeld",
};

const subjects = {
  wohngeld: "Ihr Wohngeldantrag",
  kinderzuschlag: "Ihr Kinderzuschlagantrag",
  elterngeld: "Ihr Elterngeldantrag",
  pflegegeld: "Ihr Pflegegeldantrag",
};

const body =
  antragstyp === "wohngeld" ? renderWohngeld(formData) :
  antragstyp === "pflegegeld" ? renderPflegegeld(formData) :
  renderGeneric(formData);

const html = `<!DOCTYPE html>
<html lang="de">
<head>
<meta charset="utf-8" />
<style>${baseStyles}</style>
</head>
<body>
  <header>
    <h1>${escapeHtml(titles[antragstyp] ?? "Antrag")}</h1>
    <p>Erstellt am ${generatedAt} über die Formularhilfe</p>
  </header>
  <div class="page">
    ${body}
    <footer>Dieser Antrag wurde automatisiert aus den Angaben des Antragstellers erstellt und ersetzt keine Rechtsberatung.</footer>
  </div>
</body>
</html>`;

const htmlBuffer = Buffer.from(html, "utf8");
const binaryData = await this.helpers.prepareBinaryData(htmlBuffer, "index.html", "text/html");

return {
  json: {
    antragstyp,
    email,
    quelle,
    filename: `antrag-${antragstyp}.pdf`,
    subject: subjects[antragstyp] ?? "Ihr Antrag",
  },
  binary: {
    data: binaryData,
  },
};

const fs = require("fs");
const path = require("path");

const DATA_DIR = "/home/node/.n8n/formularhilfe-data";
const CONFIG_FILE = path.join(DATA_DIR, "config.json");
const ZAEHLER_FILE = path.join(DATA_DIR, "zaehler.json");
const PENDING_FILE = path.join(DATA_DIR, "pending.json");
const SUBSCRIBERS_FILE = path.join(DATA_DIR, "subscribers.json");

function readJson(file, fallback) {
  try {
    fs.mkdirSync(DATA_DIR, { recursive: true });
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    return fallback;
  }
}

function writeJson(file, data) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  fs.writeFileSync(file, JSON.stringify(data, null, 2));
}

function readConfig() {
  return readJson(CONFIG_FILE, { wohngeld: false, kinderzuschlag: false, elterngeld: false, pflegegeld: false });
}

function readZaehler() {
  return readJson(ZAEHLER_FILE, {});
}

function readPending() {
  return readJson(PENDING_FILE, {});
}

function readSubscribers() {
  return readJson(SUBSCRIBERS_FILE, {});
}

const { antragstyp, formData, email, quelle } = $input.item.json;

const config = readConfig();
const kostenpflichtig = config[antragstyp] === true;

if (!kostenpflichtig) {
  return { json: { antragstyp, formData, email, quelle, paymentRequired: false } };
}

const subscribers = readSubscribers();
if (subscribers[email]?.status === "active") {
  return { json: { antragstyp, formData, email, quelle, paymentRequired: false } };
}

const zaehler = readZaehler();
const bisher = zaehler[email] || 0;

if (bisher < 3) {
  zaehler[email] = bisher + 1;
  writeJson(ZAEHLER_FILE, zaehler);
  return { json: { antragstyp, formData, email, quelle, paymentRequired: false } };
}

const pendingId = require("crypto").randomUUID();
const pending = readPending();
pending[pendingId] = {
  antragstyp,
  formData,
  email,
  status: "pending",
  createdAt: new Date().toISOString(),
};
writeJson(PENDING_FILE, pending);

return {
  json: {
    antragstyp,
    email,
    quelle,
    paymentRequired: true,
    pendingId,
  },
};

