const body = $input.item.json.body ?? {};
const { action, password, config: neueConfig, email: zielEmail } = body;

if (!$env.ADMIN_PASSWORD || password !== $env.ADMIN_PASSWORD) {
  return { json: { success: false, message: "Falsches Passwort." } };
}

const antragstypen = ["wohngeld", "kinderzuschlag", "elterngeld", "pflegegeld"];

if (action === "get") {
  return { json: { success: true, config: readConfig(), verified: readVerified() } };
}

if (action === "set") {
  const aktuelle = readConfig();
  for (const typ of antragstypen) {
    if (typeof neueConfig?.[typ] === "boolean") {
      aktuelle[typ] = neueConfig[typ];
    }
  }
  writeJson(CONFIG_FILE, aktuelle);
  return { json: { success: true, config: aktuelle } };
}

if (action === "delete_verified") {
  if (!zielEmail) {
    return { json: { success: false, message: "E-Mail-Adresse fehlt." } };
  }
  const verified = readVerified();
  delete verified[zielEmail];
  writeJson(VERIFIED_FILE, verified);
  return { json: { success: true, verified } };
}

return { json: { success: false, message: 'Unbekannte Aktion. Erwartet: "get", "set" oder "delete_verified".' } };

