  ["managed_payments[enabled]", "false"],
];
if (mode === "payment") {
  fields.push(["invoice_creation[enabled]", "true"]);
}
const bodyString = fields
  .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
  .join("&");

return {
  json: {
    pendingId,
    email: eintrag.email,
    antragstyp: eintrag.antragstyp,
    mode,
    priceId,
    bodyString,
  },
