}
const crypto = require("crypto");

const headers = $input.item.json.headers ?? {};
const signatureHeader = headers["stripe-signature"];
const rawBody = $input.item.binary?.data
  ? Buffer.from($input.item.binary.data.data, "base64").toString("utf8")
  : JSON.stringify($input.item.json.body ?? {});

if (!signatureHeader) {
  throw new Error("Fehlender Stripe-Signature-Header.");
}

const parts = Object.fromEntries(
  signatureHeader.split(",").map((part) => {
    const [key, value] = part.split("=");
    return [key, value];
  })
);

const secret = $env.STRIPE_WEBHOOK_SECRET;
if (!secret) {
  throw new Error("STRIPE_WEBHOOK_SECRET ist nicht konfiguriert.");
}

const signedPayload = `${parts.t}.${rawBody}`;
const expected = crypto.createHmac("sha256", secret).update(signedPayload).digest("hex");

if (expected !== parts.v1) {
  throw new Error("Ungültige Stripe-Signatur.");
}

const fiveMinutes = 5 * 60;
const nowSeconds = Math.floor(Date.now() / 1000);
if (Math.abs(nowSeconds - Number(parts.t)) > fiveMinutes) {
  throw new Error("Stripe-Signatur-Zeitstempel zu alt (mögliche Replay-Attacke).");
}

const event = JSON.parse(rawBody);

if (event.type === "customer.subscription.deleted") {
  const subscription = event.data.object;
  const subscribers = readSubscribers();
  const email = Object.keys(subscribers).find(
    (e) => subscribers[e].subscriptionId === subscription.id
  );
  if (email) {
    subscribers[email].status = "canceled";
    subscribers[email].canceledAt = new Date().toISOString();
    writeJson(SUBSCRIBERS_FILE, subscribers);
  }
  return { json: { handled: false, eventType: event.type } };
}

if (event.type !== "checkout.session.completed") {
  return { json: { handled: false, eventType: event.type } };
}

const session = event.data.object;
const pendingId = session.metadata?.pendingId;
const pending = readPending();
const eintrag = pending[pendingId];

if (!eintrag) {
  return { json: { handled: false, reason: "Unbekannte pendingId in Stripe-Event." } };
}

eintrag.status = "paid";
eintrag.paidAt = new Date().toISOString();
pending[pendingId] = eintrag;
writeJson(PENDING_FILE, pending);

const zaehler = readZaehler();
zaehler[eintrag.email] = (zaehler[eintrag.email] || 0) + 1;
writeJson(ZAEHLER_FILE, zaehler);

if (session.mode === "subscription" && session.subscription) {
  const subscribers = readSubscribers();
  subscribers[eintrag.email] = {
    subscriptionId: session.subscription,
    status: "active",
    since: new Date().toISOString(),
  };
  writeJson(SUBSCRIBERS_FILE, subscribers);
}

return {
  json: {
    handled: true,
    antragstyp: eintrag.antragstyp,
    formData: eintrag.formData,
    email: eintrag.email,
    quelle: "stripe",
  },
};

