const token = $input.item.json.body?.token;

if (!token) {
  throw new Error("Kein Bestätigungs-Token angegeben.");
}

const verifyPending = readVerifyPending();
const eintrag = verifyPending[token];

if (!eintrag) {
  throw new Error("Dieser Bestätigungslink ist ungültig oder wurde bereits verwendet.");
}

const oneDayMs = 24 * 60 * 60 * 1000;
if (Date.now() - new Date(eintrag.createdAt).getTime() > oneDayMs) {
  throw new Error("Dieser Bestätigungslink ist abgelaufen. Bitte stelle den Antrag erneut.");
}

const verified = readVerified();
verified[eintrag.email] = { verifiedAt: new Date().toISOString() };
writeJson(VERIFIED_FILE, verified);

delete verifyPending[token];
writeJson(VERIFY_PENDING_FILE, verifyPending);

return {
  json: {
    antragstyp: eintrag.antragstyp,
    formData: eintrag.formData,
    email: eintrag.email,
    quelle: "email-verify",
  },
};
